// Offline cache for the self-hosted VectorCraft web build.
// Generated by scripts/build_site.py for upstream release __TAG__.
//
// How it works
//  - install:  downloads every file of the site into one cache. Hashed files (the .js and
//              .wasm names carry a content hash) are fetched only when missing, so an update
//              that keeps a file does not download it again. index.html and the manifest are
//              always re-fetched. If anything fails, the old version stays in charge.
//  - activate: removes cached files the new version no longer lists.
//  - fetch:    cache first, so the app starts with no network. Without a cached copy the
//              request goes to the network.
// A new release changes this file, so the browser installs it in the background; the new
// version is used the next time the app is opened.

const TAG = '__TAG__';
// BUILD changes whenever index.html, the manifest or an icon changes. That changes this
// file's bytes, which is how the browser notices there is a new version to install.
const BUILD = '__BUILD__';
const CACHE = 'vectorcraft-offline';
const FILES = __FILES__;
const ALWAYS_REFRESH = new Set(['./', './index.html', './manifest.webmanifest']);

const abs = (path) => new URL(path, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Big hashed files first, the page that points at them last: if the install is cut
    // short, the old page keeps working with files that are all still there.
    const ordered = [
      ...FILES.filter((path) => !ALWAYS_REFRESH.has(path)),
      ...FILES.filter((path) => ALWAYS_REFRESH.has(path)),
    ];
    for (const path of ordered) {
      const url = abs(path);
      const refresh = ALWAYS_REFRESH.has(path);
      if (!refresh && (await cache.match(url))) continue;
      const request = refresh ? new Request(url, { cache: 'reload' }) : new Request(url);
      const response = await fetch(request);
      if (!response.ok) throw new Error('precache failed: ' + path + ' (' + response.status + ')');
      await cache.put(url, response);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const keep = new Set(FILES.map(abs));
    for (const request of await cache.keys()) {
      if (!keep.has(request.url)) await cache.delete(request);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || request.headers.has('range')) return;
  if (!request.url.startsWith(self.registration.scope)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // ignoreSearch: "?webgl" and "?cpu" still open the cached page.
    let hit = await cache.match(request, { ignoreSearch: true });
    if (!hit && request.mode === 'navigate') hit = await cache.match(abs('./index.html'));
    if (hit) return hit;
    try {
      return await fetch(request);
    } catch (error) {
      return new Response('Offline and not cached: ' + request.url, {
        status: 503,
        headers: { 'Content-Type': 'text/plain; charset=utf-8' },
      });
    }
  })());
});
